class CsvDataError(Exception):
    """Base class for all errors raised by :mod:`csvdata`."""


class CsvLoadError(CsvDataError):
    """Raised when a CSV source cannot be read or parsed."""


class ColumnNotFoundError(CsvDataError, KeyError):
    """Raised when a requested column is not present in a table."""

    def __str__(self):
        return f"column not found: {self.args[0]!r}"


class CleaningError(CsvDataError):
    """Raised when a cleaning operation cannot be completed."""


class AnalysisError(CsvDataError):
    """Raised when an analysis operation cannot be completed."""

"""Shared helpers for interpreting and classifying cell values."""

MISSING_TOKENS = frozenset(
    {"", "na", "n/a", "nan", "null", "none", "nil", "missing", "?"}
)

TRUE_TOKENS = frozenset({"true", "yes", "y", "t"})
FALSE_TOKENS = frozenset({"false", "no", "n", "f"})

DTYPES = ("int", "float", "bool", "str")


def is_missing(value):
    """Return ``True`` when *value* represents absent data."""
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip().lower() in MISSING_TOKENS
    return False


def looks_like_int(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return value.is_integer()
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return False
        try:
            int(text)
        except ValueError:
            return False
        return True
    return False


def looks_like_float(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return True
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return False
        try:
            float(text)
        except ValueError:
            return False
        return True
    return False


def looks_like_bool(value):
    if isinstance(value, bool):
        return True
    if isinstance(value, str):
        return value.strip().lower() in TRUE_TOKENS | FALSE_TOKENS
    return False


def parse_bool(value):
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in TRUE_TOKENS:
        return True
    if text in FALSE_TOKENS:
        return False
    raise ValueError(f"cannot interpret {value!r} as a boolean")


def coerce_value(value, dtype):
    """Convert *value* to *dtype*, mapping missing data to ``None``."""
    if is_missing(value):
        return None
    if dtype == "int":
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, float):
            return int(value)
        return int(str(value).strip())
    if dtype == "float":
        if isinstance(value, bool):
            return float(value)
        return float(str(value).strip())
    if dtype == "bool":
        return parse_bool(value)
    return str(value)

"""An in-memory, column-aware container for tabular data."""

from __future__ import annotations

import csv

from .errors import ColumnNotFoundError
from .values import DTYPES


class Table:
    """A simple table of named columns and homogeneous-ish rows.

    ``columns`` is a list of unique column names, ``rows`` is a list of
    equally sized lists, and ``dtypes`` maps each column name to one of
    ``"int"``, ``"float"``, ``"bool"`` or ``"str"``.
    """

    def __init__(self, columns, rows, dtypes=None):
        self.columns = [str(name) for name in columns]
        if len(set(self.columns)) != len(self.columns):
            raise ValueError("column names must be unique")
        self.rows = [list(row) for row in rows]
        width = len(self.columns)
        for position, row in enumerate(self.rows, start=1):
            if len(row) != width:
                raise ValueError(
                    f"row {position} has {len(row)} value(s); expected {width}"
                )
        if dtypes is None:
            dtypes = {}
        unknown = set(dtypes) - set(self.columns)
        if unknown:
            raise ValueError(f"dtypes reference unknown columns: {sorted(unknown)}")
        self.dtypes = {name: dtypes.get(name, "str") for name in self.columns}
        for name, dtype in self.dtypes.items():
            if dtype not in DTYPES:
                raise ValueError(f"unsupported dtype {dtype!r} for column {name!r}")

    def __len__(self):
        return len(self.rows)

    def __iter__(self):
        return iter(self.to_dicts())

    def __repr__(self):
        return f"Table(columns={self.columns!r}, rows={len(self.rows)})"

    def __eq__(self, other):
        if not isinstance(other, Table):
            return NotImplemented
        return (
            self.columns == other.columns
            and self.dtypes == other.dtypes
            and self.rows == other.rows
        )

    @property
    def shape(self):
        """Return ``(row_count, column_count)``."""
        return (len(self.rows), len(self.columns))

    def index(self, column):
        """Return the positional index of *column*."""
        try:
            return self.columns.index(column)
        except ValueError as exc:
            raise ColumnNotFoundError(column) from exc

    def __contains__(self, column):
        return column in self.columns

    def __getitem__(self, column):
        position = self.index(column)
        return [row[position] for row in self.rows]

    def get(self, column, default=None):
        """Return a column's values or *default* when it does not exist."""
        if column not in self.columns:
            return default
        return self[column]

    def to_dicts(self):
        """Return the rows as a list of dictionaries."""
        return [dict(zip(self.columns, row)) for row in self.rows]

    @classmethod
    def from_dicts(cls, records, columns=None):
        """Build a table from an iterable of mappings."""
        records = list(records)
        if columns is None:
            columns = []
            for record in records:
                for key in record:
                    if key not in columns:
                        columns.append(key)
        rows = [[record.get(column) for column in columns] for record in records]
        return cls(columns, rows)

    def head(self, n=5):
        """Return a new table with at most the first *n* rows."""
        return self._with_rows(self.rows[:n])

    def select(self, columns):
        """Return a new table containing only *columns* (in order)."""
        if isinstance(columns, str):
            columns = [columns]
        positions = [self.index(column) for column in columns]
        rows = [[row[position] for position in positions] for row in self.rows]
        dtypes = {column: self.dtypes[column] for column in columns}
        return Table(columns, rows, dtypes)

    def where(self, predicate):
        """Return rows for which ``predicate(record_dict)`` is truthy."""
        rows = [
            row
            for row in self.rows
            if predicate(dict(zip(self.columns, row)))
        ]
        return self._with_rows(rows)

    def with_column(self, name, values, dtype=None):
        """Return a copy of the table with an extra column."""
        values = list(values)
        if len(values) != len(self.rows):
            raise ValueError("column length must match the table's row count")
        rows = [row + [value] for row, value in zip(self.rows, values)]
        dtypes = dict(self.dtypes)
        dtypes[name] = dtype or "str"
        return Table(self.columns + [name], rows, dtypes)

    def _with_rows(self, rows):
        return Table(self.columns, rows, self.dtypes)

    def to_csv(self, target, delimiter=",", encoding="utf-8", include_header=True):
        """Write the table to a path or file-like object."""
        if hasattr(target, "write"):
            return self._write_csv(
                target, delimiter, include_header
            )
        with open(target, "w", newline="", encoding=encoding) as handle:
            return self._write_csv(handle, delimiter, include_header)

    def _write_csv(self, handle, delimiter, include_header):
        writer = csv.writer(handle, delimiter=delimiter)
        if include_header:
            writer.writerow(self.columns)
        for row in self.rows:
            writer.writerow(["" if value is None else value for value in row])

"""Read CSV sources into :class:`~csvdata.table.Table` objects."""

from __future__ import annotations

import csv
import io
import os

from .errors import CsvLoadError
from .table import Table
from .values import MISSING_TOKENS


def _normalise_missing(value, missing):
    if value is None:
        return None
    text = value.strip() if isinstance(value, str) else value
    if isinstance(text, str) and text.lower() in missing:
        return None
    return value


def _dedupe_headers(headers):
    seen = {}
    result = []
    for name in headers:
        key = name
        count = seen.get(key, 0)
        seen[key] = count + 1
        result.append(name if count == 0 else f"{name}_{count}")
    return result


def _parse(handle, delimiter, has_header, missing, max_rows):
    reader = csv.reader(handle, delimiter=delimiter)
    try:
        iterator = iter(reader)
        if has_header:
            try:
                header = next(iterator)
            except StopIteration:
                return Table([], [], {})
            columns = _dedupe_headers([cell.strip() for cell in header])
        else:
            first = next(iterator)
            columns = [f"column_{i + 1}" for i in range(len(first))]
            reader = _prepend(reader, first)
            iterator = iter(reader)
        rows = []
        for position, raw in enumerate(iterator, start=1):
            values = [_normalise_missing(cell, missing) for cell in raw]
            if len(values) > len(columns):
                raise CsvLoadError(
                    f"row {position} has {len(values)} fields but the header "
                    f"defines {len(columns)}"
                )
            if len(values) < len(columns):
                values.extend([None] * (len(columns) - len(values)))
            rows.append(values)
            if max_rows is not None and len(rows) >= max_rows:
                break
    except csv.Error as exc:
        raise CsvLoadError(f"could not parse CSV data: {exc}") from exc
    return Table(columns, rows, {column: "str" for column in columns})


def _prepend(reader, first_row):
    yield first_row
    yield from reader


def _read_source(source):
    if hasattr(source, "read"):
        return source
    if isinstance(source, bytes):
        return io.StringIO(source.decode("utf-8-sig"))
    raise TypeError("source must be a path, bytes, or a readable file object")


def load_csv(
    source,
    delimiter=",",
    encoding="utf-8-sig",
    has_header=True,
    missing_values=MISSING_TOKENS,
    max_rows=None,
):
    """Load tabular data from *source*.

    *source* may be a filesystem path, a ``bytes`` object, or a readable
    file-like object opened in text mode. Missing tokens are converted to
    ``None``; type inference and coercion are left to
    :func:`csvdata.cleaning.coerce_types` (or the :func:`csvdata.clean`
    convenience pipeline).
    """
    missing = frozenset(token.lower() for token in missing_values)
    if isinstance(source, (str, os.PathLike)):
        try:
            with open(source, "r", newline="", encoding=encoding) as handle:
                return _parse(handle, delimiter, has_header, missing, max_rows)
        except OSError as exc:
            raise CsvLoadError(f"could not read {source!r}: {exc}") from exc
    handle = _read_source(source)
    return _parse(handle, delimiter, has_header, missing, max_rows)


def load_csvs(sources, **kwargs):
    """Load several sources, returning ``{name: Table}``."""
    return {os.fspath(source): load_csv(source, **kwargs) for source in sources}

"""Cleaning and type-coercion operations for :class:`~csvdata.table.Table`."""

from __future__ import annotations

import statistics
from collections import Counter

from .errors import CleaningError, ColumnNotFoundError
from .table import Table
from .values import coerce_value, is_missing, looks_like_bool, looks_like_float, looks_like_int

FILL_STRATEGIES = ("drop", "constant", "mean", "median", "mode", "ffill")


def strip_whitespace(table):
    """Return a copy of *table* with surrounding whitespace removed from strings."""
    rows = [
        [value.strip() if isinstance(value, str) else value for value in row]
        for row in table.rows
    ]
    return Table(table.columns, rows, table.dtypes)


def infer_dtype(values):
    """Infer the most specific dtype able to represent *values*."""
    present = [value for value in values if not is_missing(value)]
    if not present:
        return "str"
    if all(isinstance(value, bool) for value in present):
        return "bool"
    if all(looks_like_bool(value) for value in present):
        return "bool"
    if all(looks_like_int(value) for value in present):
        return "int"
    if all(looks_like_float(value) for value in present):
        return "float"
    return "str"


def coerce_types(table, columns=None):
    """Infer and apply a dtype to each column, returning a new table."""
    targets = list(columns) if columns else list(table.columns)
    for column in targets:
        table.index(column)
    dtypes = dict(table.dtypes)
    for column in targets:
        dtypes[column] = infer_dtype(table[column])
    try:
        rows = [
            [
                coerce_value(value, dtypes[column])
                for column, value in zip(table.columns, row)
            ]
            for row in table.rows
        ]
    except (TypeError, ValueError) as exc:
        raise CleaningError(f"could not coerce column types: {exc}") from exc
    return Table(table.columns, rows, dtypes)


def drop_empty_rows(table):
    """Drop rows in which every value is missing."""
    rows = [row for row in table.rows if any(not is_missing(v) for v in row)]
    return Table(table.columns, rows, table.dtypes)


def drop_duplicates(table, subset=None):
    """Drop duplicate rows, optionally considering only *subset* columns."""
    if subset is None:
        positions = range(len(table.columns))
    else:
        if isinstance(subset, str):
            subset = [subset]
        positions = [table.index(column) for column in subset]
    seen = set()
    rows = []
    for row in table.rows:
        key = tuple(row[position] for position in positions)
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return Table(table.columns, rows, table.dtypes)


def drop_missing(table, subset=None, how="any"):
    """Drop rows containing missing values in *subset* (or all columns)."""
    if how not in ("any", "all"):
        raise ValueError("how must be 'any' or 'all'")
    columns = [subset] if isinstance(subset, str) else (subset or table.columns)
    positions = [table.index(column) for column in columns]
    rows = []
    for row in table.rows:
        missing = [is_missing(row[position]) for position in positions]
        drop = any(missing) if how == "any" else all(missing)
        if not drop:
            rows.append(row)
    return Table(table.columns, rows, table.dtypes)


def _mode(values):
    counter = Counter(values)
    if not counter:
        return None
    return counter.most_common(1)[0][0]


def _fill_value(table, column, strategy, value, present):
    if strategy == "constant":
        return value
    dtype = table.dtypes.get(column, "str")
    numeric = dtype in ("int", "float")
    numbers = []
    if numeric:
        numbers = [float(v) for v in present]
    if strategy == "mean" and numbers:
        return statistics.fmean(numbers)
    if strategy == "median" and numbers:
        return statistics.median(numbers)
    if strategy == "mode":
        return _mode(present)
    if strategy in ("mean", "median"):
        return _mode(present)
    raise CleaningError(f"unknown fill strategy: {strategy!r}")


def fill_missing(table, strategy="mean", value=None, columns=None):
    """Fill missing values using an imputation *strategy*."""
    if strategy not in FILL_STRATEGIES:
        raise ValueError(
            f"strategy must be one of {FILL_STRATEGIES}, got {strategy!r}"
        )
    targets = list(columns) if columns else list(table.columns)
    for column in targets:
        table.index(column)
    if strategy == "drop":
        return drop_missing(table, subset=targets, how="any")

    rows = [list(row) for row in table.rows]
    dtypes = dict(table.dtypes)
    if strategy == "ffill":
        for position, column in enumerate(table.columns):
            if column not in targets:
                continue
            last = None
            for row in rows:
                if is_missing(row[position]):
                    row[position] = last
                else:
                    last = row[position]
        return Table(table.columns, rows, dtypes)

    for column in targets:
        position = table.index(column)
        present = [row[position] for row in rows if not is_missing(row[position])]
        fill = _fill_value(table, column, strategy, value, present)
        for row in rows:
            if is_missing(row[position]):
                row[position] = fill
        if strategy in ("mean", "median") and dtypes.get(column) == "int":
            if fill is not None and not float(fill).is_integer():
                dtypes[column] = "float"
    return Table(table.columns, rows, dtypes)


def clean(
    table,
    *,
    strip=True,
    drop_empty=True,
    dedupe=False,
    subset=None,
    coerce=True,
    missing=None,
    value=None,
    columns=None,
):
    """Run a configurable cleaning pipeline over *table*.

    ``missing`` selects an imputation strategy from
    :data:`FILL_STRATEGIES` (or ``None`` to leave missing values in place).
    """
    result = table
    if strip:
        result = strip_whitespace(result)
    if drop_empty:
        result = drop_empty_rows(result)
    if coerce:
        result = coerce_types(result)
    if dedupe:
        result = drop_duplicates(result, subset=subset)
    if missing is not None:
        result = fill_missing(result, strategy=missing, value=value, columns=columns)
    return result


__all__ = [
    "FILL_STRATEGIES",
    "clean",
    "coerce_types",
    "drop_duplicates",
    "drop_empty_rows",
    "drop_missing",
    "fill_missing",
    "infer_dtype",
    "strip_whitespace",
    "ColumnNotFoundError",
]

"""Summary statistics and simple analytics for tables."""

from __future__ import annotations

import math
import statistics
from collections import Counter

from .errors import AnalysisError
from .table import Table
from .values import is_missing


def _present(table, column):
    return [value for value in table[column] if not is_missing(value)]


def _numbers(values):
    numbers = []
    for value in values:
        try:
            numbers.append(float(value))
        except (TypeError, ValueError):
            continue
    return numbers


def _hashable(value):
    if isinstance(value, (list, dict, set)):
        return repr(value)
    return value


def numeric_columns(table):
    """Return the names of columns stored as ``int`` or ``float``."""
    return [c for c in table.columns if table.dtypes.get(c) in ("int", "float")]


def describe(table):
    """Return a new :class:`Table` of per-column summary statistics."""
    records = []
    for column in table.columns:
        values = table[column]
        present = [value for value in values if not is_missing(value)]
        dtype = table.dtypes.get(column, "str")
        numbers = _numbers(present) if dtype in ("int", "float") else []
        record = {
            "column": column,
            "dtype": dtype,
            "count": len(present),
            "missing": len(values) - len(present),
            "unique": len({_hashable(v) for v in present}),
            "mean": statistics.fmean(numbers) if numbers else None,
            "median": statistics.median(numbers) if numbers else None,
            "stdev": statistics.stdev(numbers) if len(numbers) > 1 else None,
            "min": min(numbers) if numbers else _extreme(present, min),
            "max": max(numbers) if numbers else _extreme(present, max),
        }
        records.append(record)
    columns = [
        "column",
        "dtype",
        "count",
        "missing",
        "unique",
        "mean",
        "median",
        "stdev",
        "min",
        "max",
    ]
    return Table.from_dicts(records, columns=columns)


def _extreme(values, selector):
    if not values:
        return None
    try:
        return selector(values)
    except TypeError:
        return None


def value_counts(table, column, normalize=False, limit=None):
    """Count occurrences of each distinct value in *column*."""
    values = table[column]
    counts = Counter(_hashable(value) for value in values)
    total = sum(counts.values())
    ordered = counts.most_common(limit)
    records = []
    for value, count in ordered:
        record = {"value": value, "count": count}
        if normalize:
            record["proportion"] = count / total if total else None
        records.append(record)
    columns = ["value", "count"] + (["proportion"] if normalize else [])
    return Table.from_dicts(records, columns=columns)


def correlation(table, column_a, column_b):
    """Return the Pearson correlation coefficient between two columns."""
    pairs = [
        (a, b)
        for a, b in zip(table[column_a], table[column_b])
        if not is_missing(a) and not is_missing(b)
    ]
    if len(pairs) < 2:
        raise AnalysisError("at least two complete pairs are required")
    xs = _numbers([pair[0] for pair in pairs])
    ys = _numbers([pair[1] for pair in pairs])
    if len(xs) != len(pairs) or len(ys) != len(pairs):
        raise AnalysisError("both columns must be numeric")
    mean_x = statistics.fmean(xs)
    mean_y = statistics.fmean(ys)
    covariance = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    variance_x = sum((x - mean_x) ** 2 for x in xs)
    variance_y = sum((y - mean_y) ** 2 for y in ys)
    denominator = math.sqrt(variance_x * variance_y)
    if denominator == 0:
        raise AnalysisError("correlation is undefined for zero-variance input")
    return covariance / denominator


def aggregate(table, by, aggregations):
    """Group rows by *by* and compute *aggregations*.

    *aggregations* maps a result column name to ``(source_column, func)``
    where *func* is ``"count"``, ``"sum"``, ``"mean"``, ``"min"`` or
    ``"max"`` (or any callable accepting the list of non-missing values).
    """
    if isinstance(by, str):
        by = [by]
    positions = [table.index(column) for column in by]
    groups = {}
    for row in table.rows:
        key = tuple(row[position] for position in positions)
        groups.setdefault(key, []).append(row)

    records = []
    for key, rows in groups.items():
        record = {column: value for column, value in zip(by, key)}
        for name, (source, func) in aggregations.items():
            position = table.index(source)
            values = [row[position] for row in rows if not is_missing(row[position])]
            record[name] = _apply_aggregation(func, values)
        records.append(record)
    columns = list(by) + list(aggregations)
    return Table.from_dicts(records, columns=columns)


def _apply_aggregation(func, values):
    if callable(func):
        return func(values)
    if func == "count":
        return len(values)
    if func == "sum":
        return sum(_numbers(values))
    if func == "mean":
        numbers = _numbers(values)
        return statistics.fmean(numbers) if numbers else None
    if func == "min":
        return min(values) if values else None
    if func == "max":
        return max(values) if values else None
    raise AnalysisError(f"unsupported aggregation: {func!r}")


def summary(table):
    """Return a compact dictionary describing *table*."""
    missing = sum(
        1
        for row in table.rows
        for value in row
        if is_missing(value)
    )
    return {
        "rows": len(table.rows),
        "columns": len(table.columns),
        "missing_cells": missing,
        "dtypes": dict(table.dtypes),
    }

"""Plain-text rendering helpers."""

from __future__ import annotations

from .table import Table


def _cell(value):
    if value is None:
        return ""
    if isinstance(value, float):
        return f"{value:.6g}"
    return str(value)


def format_table(table, max_rows=None):
    """Render *table* as an aligned, GitHub-flavoured text table."""
    headers = [str(column) for column in table.columns]
    rows = [[_cell(value) for value in row] for row in table.rows]
